inline const TCHAR* RoseSoundAssetPath(int32 Id)
{
	return (Id > 0 && Id < RoseSoundCount) ? RoseSoundPaths[Id] : nullptr;
}

// HIT_SOUND(T, I): weapon hit-sound type x defender material -> sound id.
// Players take material 1 (cobjchar_actionframe.cpp).
inline int32 RoseHitSound(int32 Type, int32 Material)
{
	if (Type < 0 || Type >= 53) return 0;
	return RoseHitSoundTable[Type][FMath::Clamp(Material, 0, 2)];
}

// Load the row's imported wav and play it at a world position.
inline void RosePlaySoundId(UWorld* World, int32 Id, const FVector& At)
{
	const TCHAR* Path = RoseSoundAssetPath(Id);
	if (!World || !Path) return;
	const FString Full = FString::Printf(TEXT("%s.%s"), Path, *FPaths::GetBaseFilename(Path));
	if (USoundBase* S = LoadObject<USoundBase>(nullptr, *Full))
		UGameplayStatics::PlaySoundAtLocation(World, S, At);
}
